// « Trouver un projet » also looks in the text of the two PUDi documents (PUDI-CC-15).
// Pure functions, unit tested in rechercheDocuments.test.ts. Plain citation of the documents:
// the pages where the words of the query appear, nothing else (no interpretation).
//
// The index (data/index-documents-pudi.json, generated by scripts/pudi/genere-index-documents.py)
// maps each normalised word to the PDF FILE pages (1-based) where it appears. Same rules as the
// project search: every term must be the prefix of a word of the page (AND); terms shorter than
// 3 letters are ignored here (the index has no word shorter than 3 letters).
import type { DocumentPudi } from '../data/types';
import { urlDocument } from './documents';
import { normaliser } from './recherche';

export interface IndexDocuments {
  version: number;
  genere?: string;
  pagesFichier: Record<string, number>;
  mots: Record<string, Record<string, number[]>>;
}

/** Pages of one document where the query appears (PDF file pages, sorted). */
export interface PagesDocument {
  id: string;
  pages: number[];
}

export const MAX_LIENS_DOCUMENT = 12;
const LONGUEUR_MIN = 3;

/** Terms of the query used for the documents (normalised, 3 letters or more, no duplicates). */
export function termesDocuments(requete: string): string[] {
  return [...new Set(normaliser(requete).split(' ').filter((t) => t.length >= LONGUEUR_MIN))];
}

/** For each document of the index (in index order), the pages that contain every term. */
export function rechercherDocuments(index: IndexDocuments, requete: string): PagesDocument[] {
  const termes = termesDocuments(requete);
  if (!termes.length) return [];
  const ids = Object.keys(index.pagesFichier);
  // One set of pages per term and document: union over the words the term begins.
  const parTerme = termes.map((t) => {
    const pages: Record<string, Set<number>> = {};
    for (const [mot, docs] of Object.entries(index.mots)) {
      if (!mot.startsWith(t)) continue;
      for (const [id, liste] of Object.entries(docs)) {
        const s = (pages[id] ??= new Set());
        liste.forEach((p) => s.add(p));
      }
    }
    return pages;
  });
  const resultat: PagesDocument[] = [];
  for (const id of ids) {
    const [premier, ...autres] = parTerme.map((p) => p[id]);
    if (!premier || autres.some((s) => !s)) continue;
    const pages = [...premier].filter((p) => autres.every((s) => s.has(p))).sort((a, b) => a - b);
    if (pages.length) resultat.push({ id, pages });
  }
  return resultat;
}

/** A page link of a document: the printed number (null = cover or contents, « sommaire »). */
export interface LienPageDocument {
  pageFichier: number;
  pageImprimee: number | null;
  url: string;
}

/** Printed page of a PDF file page: file page − decalagePage; null on the pages before page 1. */
export function pageImprimee(doc: DocumentPudi, pageFichier: number): number | null {
  const n = pageFichier - (doc.decalagePage ?? 0);
  return n >= 1 ? n : null;
}

/** Link that opens the PDF at a FILE page (`urlPagePudi` takes printed pages). */
export function urlPageFichier(doc: DocumentPudi, pageFichier: number): string {
  return `${urlDocument(doc)}#page=${pageFichier}`;
}

/**
 * Links to show for a document: the pages before printed page 1 become a single « sommaire »
 * link (the first of them), then at most `max` links; `reste` = pages not shown.
 */
export function liensPagesDocument(
  doc: DocumentPudi,
  pagesFichier: number[],
  max = MAX_LIENS_DOCUMENT
): { liens: LienPageDocument[]; reste: number } {
  const tous: LienPageDocument[] = [];
  for (const p of pagesFichier) {
    const imprimee = pageImprimee(doc, p);
    if (imprimee === null && tous.some((l) => l.pageImprimee === null)) continue;
    tous.push({ pageFichier: p, pageImprimee: imprimee, url: urlPageFichier(doc, p) });
  }
  return { liens: tous.slice(0, max), reste: Math.max(0, tous.length - max) };
}
